    paths = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # East two cells, then one cell north.
                route = [(r, c + 1), (r, c + 2), (r - 1, c + 2)]
            elif color == 2:
                route = [(r, c - k) for k in range(1, 5)]
            elif color == 3:
                route = [(r + k, c) for k in range(1, 4)]
            elif color == 6:
                route = [(r - k, c) for k in range(1, 7)]
            else:
                continue
            starts.append((r, c, color))
            paths.append((color, route))

    occupied_by_routes = {}
    for color, route in paths:
        for pos in route:
            if 0 <= pos[0] < h and 0 <= pos[1] < w:
                occupied_by_routes.setdefault(pos, []).append(color)

    intersections = []
    for pos, colors in occupied_by_routes.items():
        if len(colors) > 1:
            out[pos[0]][pos[1]] = 4
            intersections.append(pos)

    for color, route in paths:
        for pos in route[:-1]:
            r, c = pos
            if 0 <= r < h and 0 <= c < w and len(occupied_by_routes.get(pos, [])) < 2 and out[r][c] == 0:
