        r, c = route[-1]
        if 0 <= r < h and 0 <= c < w and len(occupied_by_routes.get((r, c), [])) < 2 and out[r][c] == 0:
            out[r][c] = color

    for r, c in intersections:
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
